def ball_exit_columns(grid):
 answer=[]
 for start in range(len(grid[0])):
  column=start
  for row in grid:
   nxt=column+row[column]
   if nxt<0 or nxt>=len(row) or row[nxt]!=row[column]:column=-1;break
   column=nxt
  answer.append(column)
 return answer

